class MRUQueue {
public:
    int B;
    vector<vector<int>> buckets;
    MRUQueue(int n) {
        B = max(1, (int)sqrt(n));
        for (int i = 1; i <= n; i++) {
            if (buckets.empty() || buckets.back().size() == B) {
                buckets.push_back({});
            }
            buckets.back().push_back(i);
        }
    }
    int fetch(int k) {
        int idx = k - 1;
        int bIdx = 0;
        while (idx >= buckets[bIdx].size()) {
            idx -= buckets[bIdx].size();
            bIdx++;
        }
        int val = buckets[bIdx][idx];
        buckets[bIdx].erase(buckets[bIdx].begin() + idx);
        buckets.back().push_back(val);
        for (int i = bIdx; i < (int)buckets.size() - 1; i++) {
            if (buckets[i].size() < B && !buckets[i + 1].empty()) {
                buckets[i].push_back(buckets[i + 1].front());
                buckets[i + 1].erase(buckets[i + 1].begin());
            }
        }
        return val;
    }
};

class MRUQueue {
    private int B;
    private List<List<Integer>> buckets = new ArrayList<>();
    public MRUQueue(int n) {
        B = Math.max(1, (int)Math.sqrt(n));
        for (int i = 1; i <= n; i++) {
            if (buckets.isEmpty() || buckets.get(buckets.size() - 1).size() == B) {
                buckets.add(new ArrayList<>());
            }
            buckets.get(buckets.size() - 1).add(i);
        }
    }
    public int fetch(int k) {
        int idx = k - 1;
        int bIdx = 0;
        while (idx >= buckets.get(bIdx).size()) {
            idx -= buckets.get(bIdx).size();
            bIdx++;
        }
        int val = buckets.get(bIdx).remove(idx);
        buckets.get(buckets.size() - 1).add(val);
        for (int i = bIdx; i < buckets.size() - 1; i++) {
            if (buckets.get(i).size() < B && !buckets.get(i + 1).isEmpty()) {
                buckets.get(i).add(buckets.get(i + 1).remove(0));
            }
        }
        return val;
    }
}

var MRUQueue = function(n) {
    this.B = Math.max(1, Math.floor(Math.sqrt(n)));
    this.buckets = [];
    for (let i = 1; i <= n; i++) {
        if (this.buckets.length === 0 || this.buckets[this.buckets.length - 1].length === this.B) {
            this.buckets.push([]);
        }
        this.buckets[this.buckets.length - 1].push(i);
    }
};

MRUQueue.prototype.fetch = function(k) {
    let idx = k - 1;
    let bIdx = 0;
    while (idx >= this.buckets[bIdx].length) {
        idx -= this.buckets[bIdx].length;
        bIdx++;
    }
    const val = this.buckets[bIdx].splice(idx, 1)[0];
    this.buckets[this.buckets.length - 1].push(val);
    for (let i = bIdx; i < this.buckets.length - 1; i++) {
        if (this.buckets[i].length < this.B && this.buckets[i + 1].length > 0) {
            this.buckets[i].push(this.buckets[i + 1].shift());
        }
    }
    return val;
};
